/** 依次写入 ${jobsDir}/${jobId}/ 下的五份输入产物（保留阶段目录层级），返回 jobId。 */
export function writeE2EFixture(jobsDir: string, jobId = 'demo'): string {
  const jobDir = path.join(jobsDir, jobId);
  for (const [rel, content] of Object.entries(E2E_INPUTS)) {
    const file = path.join(jobDir, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
  }
  return jobId;
}
